function nmToKm(nm){
  var v=Number(nm);
  if(!isFinite(v)) return {error:'Enter a number of nautical miles.'};
  if(v<0) return {error:'Distance must be zero or more.'};
  return {nm:v, km:Math.round(v*1.852*100)/100};
}
function countFamily(fam){
  if(!fam||typeof fam!=='string') return {error:'Enter a family, for example jet.'};
  var f=fam.trim().toLowerCase();
  if(!f) return {error:'Enter a family, for example jet.'};
  if(FAMS.indexOf(f)===-1) return {error:'Family '+f+' is not one of the four archive families.'};
  var n=0; for(var i=0;i<SAMPLE.length;i++){ if(SAMPLE[i].facet===f) n++; }
  return {family:f, count:n, of:SAMPLE.length};
}
function makeFun(seed){
  var r=rng(String(seed==null?'':seed));
  var x=SAMPLE[Math.floor(r()*SAMPLE.length)];
  return 'Fun: Ginny asked the machine for "'+x.title+'" twice — and the machine handed back two, just to be safe.';
}
if (typeof module !== 'undefined' && module.exports) module.exports = { nmToKm: nmToKm, countFamily: countFamily, makeFun: makeFun };
